@pytest.fixture
def restore_app_look(qapp):
    """apply_color_scheme() changes the shared QApplication: put its style, palette and scheme back."""
    from PySide6.QtCore import Qt
    style, palette = qapp.style().name(), qapp.palette()
    yield qapp
    qapp.setStyle(style)
    qapp.setPalette(palette)
    qapp.styleHints().setColorScheme(Qt.ColorScheme.Unknown)


@pytest.mark.parametrize('value', ['', None])
def test_color_scheme_unset_changes_nothing(restore_app_look, monkeypatch, value):
    qapp = restore_app_look
    monkeypatch.delenv(ENV_COLOR_SCHEME, raising=False)
    before = qapp.palette().window().color().name()
    assert apply_color_scheme(qapp, value) == ''
    assert qapp.palette().window().color().name() == before


def test_color_scheme_dark_from_env(restore_app_look, monkeypatch):
    qapp = restore_app_look
    monkeypatch.setenv(ENV_COLOR_SCHEME, ' Dark ')
    applied = apply_color_scheme(qapp)
    assert applied in ('dark', 'dark-fusion')
    if applied == 'dark-fusion':
        assert qapp.style().name() == 'fusion'
    assert qapp.palette().window().color().lightness() < 100
    assert qapp.palette().text().color().lightness() > 200


def test_color_scheme_invalid_is_ignored(restore_app_look):
    assert apply_color_scheme(restore_app_look, 'purple') == ''


def table_column(table, header) -> list:
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == header)
    return [table.item(r, col).text() for r in range(table.rowCount())]


def test_periods_table(qtbot):
    w = QW_Periods()
    qtbot.addWidget(w)
    df = pd.DataFrame({COL_DATE: ['2024-12-31', '2025-01-02', '2025-01-10'],
                       COL_OUT: [-20.0, -10.0, 0.0], COL_IN: [0.0, 0.0, 100.0]})

    w.qcb_periods_time.setCurrentText('Monthly')
    w.update_periods(df)
    # Newest first
    assert table_column(w.table.qtw_periods, 'Date') == ['2025-01', '2024-12']
    assert table_column(w.table.qtw_periods, 'Out') == ['-10', '-20']
    assert table_column(w.table.qtw_periods, 'In') == ['100', '0']
    assert table_column(w.table.qtw_periods, 'Sum') == ['90', '-20']
    assert table_column(w.table.qtw_periods, 'Entries') == ['2', '1']
    assert w.table.qtw_periods.item(0, 3).foreground().color().name() == '#2ca02c'
    assert w.table.qtw_periods.item(1, 3).foreground().color().name() == '#d62728'

    # Changing the time frame re-renders from the stored data. Tue 31 Dec and Thu 2 Jan share the week of Mon 30 Dec
    w.qcb_periods_time.setCurrentText('Weekly')
    assert table_column(w.table.qtw_periods, 'Date') == ['2025-01-06', '2024-12-30']
    w.qcb_periods_time.setCurrentText('Yearly')
    assert table_column(w.table.qtw_periods, 'Date') == ['2025', '2024']

    w.update_periods(df.iloc[0:0])
    assert w.table.qtw_periods.rowCount() == 0


