def test_movements_table_sorts_and_keeps_user_sort(qtbot):
    from PySide6.QtCore import Qt
    w = QW_MovementsTable()
    qtbot.addWidget(w)
    # Extra columns (e.g. Class) are ignored, only the header ones are shown
    df = movements([('2025-01-02', -10.0, 0.0, 'B', 'x'), ('2025-01-03', -2.0, 0.0, 'A', 'x'),
                    ('2025-01-01', 0.0, 3.5, 'C', 'x')])

    w.show_movements(df)

    table = w.qtw_movements
    assert table_column(table, COL_DESCR) == ['A', 'B', 'C']  # newest first
    assert table_column(table, COL_OUT) == ['-2.00', '-10.00', '']  # 0 is blank
    assert not table.item(0, 0).flags() & Qt.ItemFlag.ItemIsEditable

    table.sortItems(1, Qt.SortOrder.AscendingOrder)  # the user clicks the Out header: numeric sort
    w.show_movements(df.iloc[::-1])
    assert table_column(table, COL_DESCR) == ['B', 'A', 'C']


def test_static_columns_reject_unknown_header(qtbot):
    from PySide6.QtWidgets import QTableWidget
    qtw = QTableWidget(0, 2)
    qtbot.addWidget(qtw)
    qtw.setHorizontalHeaderLabels(['Date', 'Descrption'])

    with pytest.raises(ValueError, match="unknown column headers \\['Descrption'\\]"):
        StaticColumnsTable(qtw, known=['Date', 'Description'])


def movements(rows) -> pd.DataFrame:
    """Visible ledger rows, as MainWindow.df_plot: (date, out, in, description, class)."""
    df = pd.DataFrame(rows, columns=[COL_DATE, COL_OUT, COL_IN, COL_DESCR, COL_CLASS])
    df[COL_AMOUNT] = df[COL_OUT] + df[COL_IN]
    return df


ROWS = [('2025-01-02', -10.0, 0.0, 'PIZZA', 'food'), ('2025-01-03', 0.0, 100.0, 'SALARY', CLASS_TODO),
        ('2025-01-04', -5.0, 0.0, 'BREAD', 'food'), ('2025-01-05', -1.0, 0.0, 'FEE', 'bank')]


def tab_texts(w) -> list:
    return [w.qtw_tabs.tabText(i) for i in range(w.qtw_tabs.count())]


def test_classes_one_tab_per_class(qtbot):
    w = QW_Classes()
    qtbot.addWidget(w)

    w.update_classes(movements(ROWS))

    assert tab_texts(w) == ['bank', 'food', CLASS_TODO]
    food = w.class_tables()['food']
    assert w.qtw_tabs.widget(1) is food
    table = food.qtw_movements
    assert [table.horizontalHeaderItem(c).text() for c in range(table.columnCount())] == \
        [COL_DATE, COL_OUT, COL_IN, COL_DESCR]  # from movements_table.ui
    # Newest first, blank In
    assert table_column(table, COL_DESCR) == ['BREAD', 'PIZZA']
    assert table_column(table, COL_OUT) == ['-5.00', '-10.00']
    assert table_column(table, COL_IN) == ['', '']
    from PySide6.QtWidgets import QHeaderView
    assert table.horizontalHeader().sectionResizeMode(3) == QHeaderView.ResizeMode.Stretch  # Description


def test_classes_tabs_follow_visible_rows(qtbot):
    w = QW_Classes()
    qtbot.addWidget(w)
    w.update_classes(movements(ROWS))
    food = w.class_tables()['food']
    w.qtw_tabs.setCurrentIndex(1)  # food

    # e.g. the bank class unchecked in the filters, and a date range without salary
    w.update_classes(movements([r for r in ROWS if r[4] == 'food']))

    assert tab_texts(w) == ['food']
    assert w.class_tables()['food'] is food  # reused, so its sort is kept
    assert w.qtw_tabs.currentWidget() is food

    w.update_classes(movements([]))
    assert w.qtw_tabs.count() == 0 and w.class_tables() == {}


def test_classes_one_aggr_stats_per_class(qtbot):
    w = QW_Classes()
    qtbot.addWidget(w)

    w.update_classes(movements(ROWS))

    boxes = w.class_aggr_stats()
    assert list(boxes) == ['bank', 'food', CLASS_TODO]
    assert [b.qgb.title() for b in boxes.values()] == ['bank', 'food', CLASS_TODO]
    assert all(b.parent() is w.qsac_aggr for b in boxes.values())
    food = boxes['food']
    assert food.ql_entries.text().strip() == '2' and food.ql_sum.text() == '-15'
    assert '#d62728' in food.ql_sum.styleSheet()  # coloured like the ledger's All box

    # Same lifecycle as the tabs: kept while visible, dropped when not, in display order
    w.update_classes(movements([r for r in ROWS if r[4] != 'bank']))
    assert list(w.class_aggr_stats()) == ['food', CLASS_TODO]
    assert w.class_aggr_stats()['food'] is food
    layout = w.qsac_aggr.layout()
    assert [layout.itemAt(i).widget() for i in range(layout.count() - 1)] == [food, w.class_aggr_stats()[CLASS_TODO]]


def test_classes_aggr_stats_scroll_vertically_only(qtbot):
    from PySide6.QtCore import Qt
    w = QW_Classes()
    qtbot.addWidget(w)
    w.update_classes(movements([('2025-01-02', -1.0, 0.0, 'X', f'class {i}') for i in range(12)]))
    w.resize(900, 400)
    w.show()
    qtbot.waitExposed(w)

    sa = w.qsa_aggr
    assert sa.horizontalScrollBarPolicy() == Qt.ScrollBarPolicy.ScrollBarAlwaysOff
    assert sa.verticalScrollBar().maximum() > 0  # 12 boxes can't fit in 400 px
    assert sa.viewport().width() >= w.qsac_aggr.layout().sizeHint().width()  # nothing clipped sideways


def pie(fig) -> dict:
    """{label: (value, colour)} of a class pie figure."""
    trace = fig.data[0]
    return {lbl: (val, col) for lbl, val, col in zip(trace.labels, trace.values, trace.marker.colors)}


def test_class_colors_by_volume_whole_data():
    # Volume = |Out| + In: food 15, todo 100, bank 1
    colors = assign_class_colors(movements(ROWS))

    assert colors == {CLASS_TODO: CLASS_PALETTE[0], 'food': CLASS_PALETTE[1], 'bank': CLASS_PALETTE[2]}


def test_class_colors_past_the_palette_fold_into_other():
    rows = [('2025-01-02', -float(i + 1), 0.0, 'X', f'c{i:02d}') for i in range(10)]
    colors = assign_class_colors(movements(rows))

    # 7 colours for the 7 largest, the 8th slot is Other's grey
    assert list(colors) == [f'c{i:02d}' for i in range(9, 2, -1)]
    fig = class_pie_figure(movements(rows), COL_OUT, colors, 'Out')
    slices = pie(fig)
    assert list(slices) == [f'c{i:02d}' for i in range(9, 2, -1)] + [CLASS_OTHER]
    assert slices[CLASS_OTHER] == (1 + 2 + 3, CLASS_OTHER_COLOR)
    assert 'c00, c01, c02' in fig.data[0].customdata[-1]


def test_class_pie_out_and_in():
    df = movements(ROWS)
    colors = assign_class_colors(df)

    out = class_pie_figure(df, COL_OUT, colors, 'Out by class')
    # Absolute sums, in colour order, the todo class has no outflow
    assert pie(out) == {'food': (15.0, CLASS_PALETTE[1]), 'bank': (1.0, CLASS_PALETTE[2])}
    assert out.layout.title.text == 'Out by class: 16.00 EUR'
    assert list(out.data[0].customdata) == ['2 movements', '1 movements']
    assert pie(class_pie_figure(df, COL_IN, colors, 'In')) == {CLASS_TODO: (100.0, CLASS_PALETTE[0])}


def test_class_pie_nothing_to_show():
    df = movements([r for r in ROWS if r[2] == 0.0])  # no inflows

    assert class_pie_figure(df, COL_IN, assign_class_colors(df), 'In') is None


def test_classes_pies_follow_visible_rows_without_repainting(qtbot):
    w = QW_Classes()
    qtbot.addWidget(w)
    w.set_class_colors(assign_class_colors(movements(ROWS)))  # from the whole data, as MainWindow does

    w.update_classes(movements(ROWS))
    assert set(pie(w.pie_figures()[COL_OUT])) == {'food', 'bank'}
    food_color = pie(w.pie_figures()[COL_OUT])['food'][1]

    # Filtered: bank gone, food keeps its colour
    w.update_classes(movements([r for r in ROWS if r[4] != 'bank']))
    assert pie(w.pie_figures()[COL_OUT]) == {'food': (15.0, food_color)}

    w.update_classes(movements([]))
    assert w.pie_figures() == {COL_OUT: None, COL_IN: None}
